package Actions_1ActionDefinition {
    private import ScalarValues::*;
    private import SysML::*;
    // Wrapped Snippet (Action Context)
    action def Main {
        action def Serve {
           in speed : Speed;
           out result : Result;
           first toss;
           then strike;
        }
    }

    view ExposeExample {
        expose Main;
    }
}

package Actions_2ActionUsage {
    private import ScalarValues::*;
    private import SysML::*;
    // Wrapped Snippet (Action Context)
    action def Main {
        action playPoint {
           action serve : Serve;
           perform serve { ... }
           action serve2 : Serve;
           perform action serve2;
        }
    }

    view ExposeExample {
        expose Main;
    }
}

package Actions_4Parameters {
